CREATE TABLE "ListasMateriales" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ProductoId" integer NOT NULL,
    "Version" integer NOT NULL,
    "Estado" character varying(10) NOT NULL,
    CONSTRAINT "PK_ListasMateriales" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ListasMateriales_Productos_ProductoId"
        FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ListasMateriales_Version" CHECK ("Version" > 0),
    CONSTRAINT "CK_ListasMateriales_Estado" CHECK ("Estado" IN ('Borrador', 'Activa', 'Retirada'))
);

CREATE UNIQUE INDEX "IX_ListasMateriales_ProductoId_Version"
    ON "ListasMateriales" ("ProductoId", "Version");
CREATE UNIQUE INDEX "IX_ListasMateriales_ProductoId_Activa"
    ON "ListasMateriales" ("ProductoId") WHERE "Estado" = 'Activa';

CREATE TABLE "DetallesListaMaterial" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ListaMaterialId" integer NOT NULL,
    "ComponenteProductoId" integer NOT NULL,
    "Cantidad" numeric(18,6) NOT NULL,
    "UnidadMedida" character varying(20) NOT NULL,
    CONSTRAINT "PK_DetallesListaMaterial" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DetallesListaMaterial_ListasMateriales_ListaMaterialId"
        FOREIGN KEY ("ListaMaterialId") REFERENCES "ListasMateriales" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_DetallesListaMaterial_Productos_ComponenteProductoId"
        FOREIGN KEY ("ComponenteProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_DetallesListaMaterial_Cantidad" CHECK ("Cantidad" > 0),
    CONSTRAINT "CK_DetallesListaMaterial_UnidadMedida" CHECK (btrim("UnidadMedida") <> '')
);

CREATE UNIQUE INDEX "IX_DetallesListaMaterial_ListaMaterialId_ComponenteProductoId"
    ON "DetallesListaMaterial" ("ListaMaterialId", "ComponenteProductoId");
CREATE INDEX "IX_DetallesListaMaterial_ComponenteProductoId"
    ON "DetallesListaMaterial" ("ComponenteProductoId");
